  'replace.title': 'Replace & graft',
  'replace.intro':
    'git replace tells git to read one object wherever another was asked for. Nothing is rewritten and no sha changes — which makes it the honest way to shorten a clone: graft a commit onto no parents and everything before it drops out of every walk, still stored, still there to put back.',
  'replace.none': 'No replacements. Git is showing you exactly what is stored.',
  'replace.disabled':
    'core.useReplaceRefs is false here, so git is ignoring every replacement below — history reads as it is actually stored.',
  'replace.parents': '{n} parents',
  'replace.noParents': 'no parents — a root commit',
  'replace.remove': 'Remove this replacement',
  'replace.graftTitle': 'Graft a commit',
  'replace.graftHint':
    'Give a commit new parents. Leave the parents empty to make it the start of history; name an archive repository\'s commit to give the full history back.',
  'replace.commit': 'Commit to graft',
  'replace.newParents': 'New parents',
  'replace.newParentsHint': 'Space-separated. Empty makes it a root commit.',
  'replace.graft': 'Graft',
  'replace.honour': 'Honour replacements here',
  'replace.rootTitle': 'Make this the start of history?',
  'replace.rootMessage':
    'Every commit before {sha} will disappear from the log, the graph and every clone made from here. Nothing is deleted — the objects stay until a gc prunes them, and removing the replacement brings the history straight back.',
  'replace.rootOk': 'Graft it',
  'replace.shareHint':
    'Replacements are refs under refs/replace/, so they are local until pushed: git push origin "refs/replace/*" shares them, and a clone that lacks them sees the untouched history.',
