  'attrs.title': 'File attributes',
  'attrs.intro':
    '.gitattributes is how a repository teaches git about its own files: which are binary, which should concatenate instead of conflicting, which stay out of an archive, what line endings to use. It travels with the clone, so fixing it here fixes it for everyone.',
  'attrs.none': 'No rules yet. The presets below cover the cases that come up most.',
  'attrs.localFile':
    'This file lives in .git/info/ — it applies only on this machine and is never committed or shared.',
  'attrs.add': 'Add rule',
  'attrs.remove': 'Remove',
  'attrs.removeTitle': 'Remove this rule?',
  'attrs.removeMessage': 'The rule for {pattern} will be deleted from the file. Undo puts it back.',
  'attrs.preset.union': 'Changelog that never conflicts',
  'attrs.preset.binary': 'Treat as binary',
  'attrs.preset.nomerge': 'Never three-way merge',
  'attrs.preset.exportIgnore': 'Keep out of archives',
  'attrs.preset.lf': 'Normalise line endings',
  'attrs.preset.lfs': 'Track with LFS',
  'attrs.preset.linguist': 'Exclude from language stats',
  'attrs.checkTitle': 'What applies to a path?',
  'attrs.checkHint':
    'Rules come from several files and the last match wins, so reading them is guesswork. This asks git itself.',
  'attrs.check': 'Check',
  'attrs.checkNothing': 'Nothing is set for this path.',
  'attrs.driversTitle': 'Diff drivers',
  'attrs.driversHint':
    'A diff driver turns an unreadable file into text before git compares it, so a Word document or a spreadsheet has a history you can actually read. Word, Excel and JSON use the converter Gitcito ships; the rest are offered when installed and greyed out when not.',
  'attrs.driverMissing': 'converter not installed',
  'attrs.needsBinary': 'Needs {binary} on your PATH.',
  'attrs.bundledConverter': 'Included with Gitcito — nothing to install.',
  'attrs.driverEphemeral': "points into a temporary AppImage folder",
  'attrs.driverEphemeralHint': "An AppImage build of Gitcito set this converter. Its folder under /tmp vanishes when the app quits, and anyone else on this machine could put a program at that path for your next git diff to run. Remove it.",
  'attrs.driverStale': 'converter predates 4.39',
  'attrs.driverStaleHint': 'This converter is the one versions up to 4.38 shipped under the app\'s old name. The app repoints such drivers to its current converter by itself; this one could not be repointed: an AppImage\'s path changes at every launch, or the config could not be written. Diffs of these files fail unless the old install is still in place. Remove it, then add the driver again from the suggestions below.',
  'attrs.driverRemove': "Remove",
  'attrs.bundledAppImage': "Not available in the AppImage: Gitcito's converter only exists while the app is running. Install the .deb package to use it.",
  'attrs.filtersTitle': 'Clean/smudge filters',
  'attrs.filtersHint': 'A filter rewrites file content on the way in (clean, at staging) and on the way out (smudge, at checkout) — how git-lfs and key-stripping work. A wrong one corrupts your working tree quietly, so Gitcito insists on a dry run against real files before saving anything.',
  'attrs.filterCleanPh': 'clean command (stdin → stdout)',
  'attrs.filterSmudgePh': 'smudge command (optional)',
  'attrs.filterRequired': 'Required — fail the operation instead of passing files through',
  'attrs.filterDryRun': 'Dry run',
  'attrs.filterDryRunFirst': 'Run the dry run on these exact values first.',
  'attrs.filterSave': 'Save filter',
  'attrs.filterNoMatches': 'No tracked files match this pattern — nothing could be tested.',
  'attrs.filterMatched': 'Matching files: {n} · tested: {m}.',
  'attrs.filterRoundtripOk': 'roundtrip OK — smudge(clean(file)) reproduces the original',
  'attrs.filterRoundtripDifferent': 'roundtrip differs — checking out would not restore the original bytes',
  'attrs.filterRoundtripSkipped': 'clean ran — no smudge command, so no roundtrip check',
  'attrs.filterDangerTitle': 'Save an unverified filter?',
  'attrs.filterDangerMessage': 'The dry run could not verify "{name}": a command failed, nothing matched, or the roundtrip does not reproduce the original bytes. If it is wrong, every checkout of matching files can silently corrupt your working tree.',
  'attrs.filterDangerConfirm': 'Save anyway',
  'attrs.filterRemoveTitle': 'Remove filter?',
  'attrs.filterRemoveMessage': 'This clears filter.{name}.clean/smudge from your git config. .gitattributes rules pointing at it stay; without required, matching files then pass through unchanged.',
  'cmd.objects': 'Object explorer',
  'objects.title': 'Object explorer',
  'objects.intro': 'Everything git stores is four kinds of object — commits, trees, blobs, tags — and refs pointing at them. Walk them here. Nothing on this page changes anything.',
  'objects.resolve': 'Go',
  'objects.back': 'Back',
  'objects.openTree': 'The tree this commit points at — its snapshot of the files',
  'objects.emptyTree': 'An empty tree. Git can store one, and this is it.',
  'objects.binary': 'Binary content, {size}. Nothing readable to show.',
  'objects.truncated': 'Only the start of this blob is shown.',
  'cmd.mergeOptions': 'Merge with options…',
